namespace KlikerBlocks;

internal static class JournalHelp
{
    internal static string? Section(string title)
    {
        if (title != "Журнал и запись в файл" || UiLanguage.Code == "ru") return null;
        return UiLanguage.Code switch
        {
"en" => "Check 'Log actions' in a block to record its short ID, actual output, resolved field values and variable/array writes. Example: Name=\"counter\", Value=\"5\"; changes: counter=\"5\". Errors also record changes made before the error. Values are shortened to 180 characters; array summaries show their size and first three items. Unchecked blocks do not add detailed traces, but explicit messages and Kliker Blocks diagnostics remain. In code view, add trace true to a block. Every block in the built-in showcase is checked. Logs can contain personal text: do not trace passwords or tokens.\n\nUse Wrap lines in the journal header, including its separate window, to fit long entries to the current width. Turn it off for single-line display. The choice is saved; it changes only the display, not log file contents.\n\nScenario → Write journal to text file records the full run in a .txt/.log file beside the saved project, or beside Kliker.Blocks.exe for an unsaved project. The absolute path appears in settings and the on-screen journal. UTF-8 data is appended up to 8 MiB; write failures are reported. The separate Log file block writes only explicit script messages.",
            "fr" => "Cochez « Journaliser les actions » dans un bloc pour enregistrer son identifiant, la sortie réelle, les paramètres résolus et les variables ou tableaux modifiés. Exemple : Name=\"counter\", Value=\"5\" ; modifications : counter=\"5\". Une erreur conserve les changements déjà effectués. Les longues valeurs sont limitées à 180 caractères ; un tableau affiche sa taille et ses trois premiers éléments. Un bloc non coché ne crée pas de trace détaillée, mais les messages explicites restent visibles. Dans le code, utilisez trace true. Tous les blocs de la démo sont cochés. Le journal peut contenir des données privées : évitez les mots de passe.\n\nScénario → Écrire le journal dans un fichier crée un .txt/.log près du projet, ou de Kliker.Blocks.exe si le projet n'est pas enregistré. Le chemin absolu est affiché. Le fichier UTF-8 est complété jusqu'à 8 Mio ; les erreurs d'écriture sont signalées. Le bloc Fichier journal n'écrit que les messages explicites.",
            "es" => "Marque « Registrar acciones » en un bloque para guardar su ID, salida real, parámetros resueltos y valores cambiados de variables o matrices. Ejemplo: Name=\"counter\", Value=\"5\"; cambios: counter=\"5\". Si hay error, se registran también los cambios previos. Los valores largos se limitan a 180 caracteres; las matrices muestran tamaño y tres elementos iniciales. Los bloques sin marcar no producen traza detallada, pero los mensajes explícitos permanecen. En el código use trace true. Todos los bloques de la demo están marcados. El registro puede contener datos privados: evite contraseñas.\n\nEscenario → Escribir registro en archivo crea un .txt/.log junto al proyecto guardado, o junto a Kliker.Blocks.exe si no se guardó. Se muestra la ruta completa. El archivo UTF-8 se añade hasta 8 MiB; los errores se notifican. El bloque Archivo de registro escribe solo mensajes explícitos.",
            "zh" => "勾选积木的“记录操作”，即可记录短 ID、实际出口、解析后的字段及变量或数组的变化。例如 Name=\"counter\"、Value=\"5\"；变更：counter=\"5\"。出错前已发生的变化也会记录。长值截为 180 字符；数组摘要显示大小和前三项。未勾选的积木不生成详细跟踪，但显式消息仍保留。代码视图中可写 trace true。内置演示的所有积木均已勾选。日志可能包含私密文字，请勿记录密码。\n\n“场景 → 将日志写入文本文件”在已保存项目旁创建 .txt/.log；未保存项目则在 Kliker.Blocks.exe 旁创建。界面显示绝对路径。UTF-8 内容追加至 8 MiB，写入失败会报告。“日志文件”积木只写入显式脚本消息。",
            "de" => "Aktivieren Sie „Aktionen protokollieren“ im Block, um kurze ID, tatsächlichen Ausgang, aufgelöste Felder und Änderungen an Variablen oder Arrays zu erfassen. Beispiel: Name=\"counter\", Value=\"5\"; Änderungen: counter=\"5\". Auch Änderungen vor einem Fehler werden aufgezeichnet. Lange Werte werden auf 180 Zeichen gekürzt; Arrays zeigen Größe und die ersten drei Elemente. Ohne Häkchen entsteht keine detaillierte Spur, ausdrückliche Meldungen bleiben sichtbar. Im Code verwenden Sie trace true. Alle Demo-Blöcke sind markiert. Das Journal kann private Texte enthalten: keine Passwörter protokollieren.\n\nSzenario → Journal in Textdatei schreiben erstellt eine .txt/.log-Datei neben dem gespeicherten Projekt oder neben Kliker.Blocks.exe. Der absolute Pfad wird angezeigt. UTF-8 wird bis 8 MiB angehängt; Schreibfehler werden gemeldet. Der separate Journaldatei-Block schreibt nur ausdrückliche Skriptmeldungen.",
            _ => null
        };
    }
}
